begin;
do $test$
declare u uuid:=gen_random_uuid(); v uuid:=gen_random_uuid(); r uuid; p uuid; p2 uuid; response jsonb; ver uuid; d uuid; snap jsonb; n integer;
begin
 insert into auth.users(id,aud,role,is_anonymous) values(u,'authenticated','authenticated',true),(v,'authenticated','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 response=public.create_drive_duel_room(upper(substr(replace(gen_random_uuid()::text,'-',''),1,6)),'nfl','Queue Test');
 r=(response->>'room_id')::uuid;p=(response->>'player_id')::uuid;
 insert into public.room_members(room_id,user_id) values(r,v);
 insert into public.players(room_id,player_name,user_id,is_cpu,score) values(r,'Fallback Test',v,false,0) returning id into p2;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 perform public.drive_duel_apply_feed(r,'queue-test','{"available":true,"revision":0,"state":"pre","completed":[],"current":null}',0,0);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 response=public.drive_duel_queue_pick(r,'queue-test','offense','Punt');ver=(response->>'version')::uuid;
 response=public.drive_duel_queue_pick(r,'queue-test','offense','Touchdown',ver);ver=(response->>'version')::uuid;
 perform public.drive_duel_queue_pick(r,'queue-test','offense',null,ver,true);
 if exists(select 1 from public.queued_predictions where room_id=r) then raise exception 'Cancel failed'; end if;
 response=public.drive_duel_queue_pick(r,'queue-test','offense','Touchdown');ver=(response->>'version')::uuid;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 snap='{"available":true,"revision":1,"state":"in","completed":[],"current":{"source_id":"q1","number":1,"quarter":1,"plays":0,"terminal":false}}';
 perform public.drive_duel_apply_feed(r,'queue-test',snap,0,0);
 select consumed_drive_id into d from public.queued_predictions where room_id=r;
 if d is null or not exists(select 1 from public.predictions where drive_id=d and player_id=p and predicted_outcome='Touchdown' and is_locked) then raise exception 'Auto-lock failed'; end if;
 if not exists(select 1 from public.drives where id=d and not feed_closed and prediction_deadline>clock_timestamp()+interval '28 seconds') then raise exception '30 second fallback missing'; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 begin
  perform public.drive_duel_queue_pick(r,'queue-test','offense','Punt',ver);
  raise exception 'Consumed pick was editable';
 exception when others then if sqlerrm='Consumed pick was editable' then raise; end if; end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);
 perform public.drive_duel_lock_prediction(d,'offense','Punt');
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 snap='{"available":true,"revision":2,"state":"in","completed":[{"source_id":"q1","number":1,"quarter":1,"confirmed":true,"terminal":true,"outcome":"Touchdown","conversion_success":true}],"current":{"source_id":"q2","number":2,"quarter":1,"plays":0,"terminal":false}}';
 perform public.drive_duel_apply_feed(r,'queue-test',snap,7,0);
 update public.drives set pending_since=clock_timestamp()-interval '3 seconds' where id=d;
 perform public.drive_duel_apply_feed(r,'queue-test',snap,7,0);
 perform public.drive_duel_apply_feed(r,'queue-test',snap,7,0);
 select score into n from public.players where id=p;
 if n<>12 then raise exception 'Exactly-once TD scoring failed: %',n; end if;
 if exists(select 1 from public.predictions pr join public.drives dr on dr.id=pr.drive_id where dr.room_id=r and dr.feed_drive_id='q2' and pr.player_id=p) then raise exception 'Queue repeated'; end if;
 -- Queue at source 2, then catch up after both source 3 and source 4 have passed.
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 response=public.drive_duel_queue_pick(r,'queue-test','offense','Punt');
 if (response->>'after_source_number')::integer<>2 then raise exception 'Wrong queue anchor'; end if;
 perform set_config('request.jwt.claims','{"role":"service_role"}',true);
 snap='{"available":true,"revision":5,"state":"in","completed":[{"source_id":"q1","number":1,"quarter":1,"confirmed":true,"outcome":"Touchdown","conversion_success":true},{"source_id":"q2","number":2,"quarter":1,"confirmed":true,"outcome":"Punt"},{"source_id":"q3","number":3,"quarter":1,"confirmed":true,"terminal":true,"outcome":"Punt"},{"source_id":"q4","number":4,"quarter":1,"confirmed":true,"terminal":true,"outcome":"Field Goal"}],"current":{"source_id":"q5","number":5,"quarter":2,"plays":0,"terminal":false}}';
 perform public.drive_duel_apply_feed(r,'queue-test',snap,7,3);
 if not exists(select 1 from public.queued_predictions q join public.drives dr on dr.id=q.consumed_drive_id where q.room_id=r and dr.feed_drive_id='q3') then raise exception 'Catch-up targeted wrong possession'; end if;
 update public.drives set pending_since=clock_timestamp()-interval '3 seconds' where room_id=r and status='awaiting_result';
 perform public.drive_duel_apply_feed(r,'queue-test',snap,7,3);
 select score into n from public.players where id=p;
 if n<>22 then raise exception 'Catch-up score wrong: %',n; end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 perform public.drive_duel_queue_pick(r,'queue-test','defense','Force a punt');
 perform set_config('test.queue_room',r::text,true);perform set_config('test.queue_owner',u::text,true);perform set_config('test.queue_other',v::text,true);
end $test$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.queue_other'),'role','authenticated')::text,true);
do $$begin if exists(select 1 from public.queued_predictions where room_id=current_setting('test.queue_room')::uuid) then raise exception 'Queued pick leaked to opponent'; end if; end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.queue_owner'),'role','authenticated')::text,true);
do $$begin if (select count(*) from public.queued_predictions where room_id=current_setting('test.queue_room')::uuid)<>2 then raise exception 'Owner cannot read queue'; end if; end$$;
reset role;
select 'PASS: edit/cancel, automatic locking, shared 30s fallback, no editing after lock, exactly-once scoring, no repeat, catch-up earliest possession, opponent privacy' as result;
rollback;